import java.util.Scanner;
import java.util.Stack;

public class sd3 {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int w = s.nextInt();
        int m = s.nextInt();

        Stack<Integer> digits = new Stack<Integer>();
        int cntr = 0;
        while (m > 0) {
            if (cntr == 40) {
                throw new ArrayIndexOutOfBoundsException(cntr);
            }
            digits.push(m % w);
            m /= w;
            cntr++;
        }

        Stack<Integer> process = new Stack<Integer>();
        process.push(0);
        while (!digits.isEmpty()) {
            process.push(digits.pop());
        }

        boolean flag = true;
        while (!process.isEmpty()) {
            int d = process.pop();
            if (d != 0 && d != 1 && d != w && d != w - 1) {
                flag = false;
                break;
            }
            if (d == w || d == w - 1) {
                if (!process.isEmpty()) {
                    process.push(process.pop() + 1);
                }
            }
        }

        System.out.println(flag ? "YES" : "NO");
    }
}
